using IntVector = std::vector<int>;

// Define stack adapter using std::vector as the base
std::stack<int, IntVector> execution_log;

// LIFO operations
execution_log.push(10);
execution_log.push(20);

// Read top element (20)
int current_top = execution_log.top();

// Remove top element
execution_log.pop();

// Check state
bool empty_check = execution_log.empty();
size_t count = execution_log.size();

// Initialization from existing vector data
IntVector tasks = {100, 200, 300};
std::stack<int, IntVector> history(tasks);

history.pop(); // Removes 300 (LIFO)
